.grouping-hint {min-height:38px;background:var(--g-color-base-generic-ultralight);border-top:1px solid var(--g-color-line-generic);border-bottom:1px solid var(--g-color-line-generic);display:flex;align-items:center;gap:var(--g-spacing-2);padding:var(--g-spacing-2) var(--g-spacing-5);font-size:10px;color:var(--g-color-text-secondary);}
