.group-count {font-size:10px;font-weight:400;color:var(--g-color-text-secondary);background:var(--g-color-base-generic);border-radius:var(--g-border-radius-s);padding:0 var(--g-spacing-2);margin-left:var(--g-spacing-1);}
.customer {display:flex;align-items:center;gap:var(--g-spacing-3);}
.customer-info {min-width:0;}
