.refunded,.muted {color:var(--g-color-text-secondary);}
.selected-row {background:var(--g-color-base-selection);}
.table-footer {padding:var(--g-spacing-4) var(--g-spacing-5);border-top:1px solid var(--g-color-line-generic);display:flex;align-items:center;justify-content:space-between;gap:var(--g-spacing-4);font-size:10px;color:var(--g-color-text-secondary);}
