.modal-content label,.settings-panel label {display:flex;flex-direction:column;gap:var(--g-spacing-2);margin:var(--g-spacing-4) 0;font-size:12px;}
.modal-actions {display:flex;justify-content:flex-end;gap:var(--g-spacing-3);margin-top:var(--g-spacing-6);}
