.toast {position:fixed;bottom:var(--g-spacing-6);left:50%;transform:translateX(-50%);z-index:10000;display:flex;align-items:center;gap:var(--g-spacing-3);padding:var(--g-spacing-3) var(--g-spacing-4);border:1px solid var(--g-color-line-generic);border-radius:var(--g-border-radius-l);background:var(--g-color-base-background);box-shadow:0 4px 24px var(--g-color-sfx-shadow);font-size:12px;}
