@media(min-width:1600px){.main-content {padding-top:var(--g-spacing-9);}.stats-grid {gap:var(--g-spacing-5);}.stat-card {padding:var(--g-spacing-5) var(--g-spacing-6);}}
@media(max-width:1250px){.main-content {padding:var(--g-spacing-6);}.topbar {padding:0 var(--g-spacing-6);}.stat-card {padding:var(--g-spacing-4);}.stat-value.revenue {--g-text-display-1-font-size:22px;}.stat-bottom {font-size:9px;gap:var(--g-spacing-1);}.order-tabs {gap:var(--g-spacing-4);}.table-toolbar {gap:var(--g-spacing-2);}.order-search {width:270px;}.filter-actions {gap:var(--g-spacing-2);}.column-button-text {display:none;}.drag-hint {font-size:9px;}.heading-tag {display:none;}}
@media(max-width:1000px){.live-indicator {display:none;}.stats-grid {gap:var(--g-spacing-3);}.stat-top {font-size:11px;}.stat-icon {width:28px;height:28px;}.stat-bottom {flex-wrap:wrap;}.stat-value.revenue {--g-text-display-1-font-size:20px;}.table-toolbar {flex-wrap:wrap;}.order-search {flex:1;min-width:230px;}.filter-actions {margin-left:auto;}.drag-hint,.hint-divider {display:none;}.users-grid {grid-template-columns:repeat(2,minmax(0,1fr));}}
@media(max-width:700px){.main-content {padding:var(--g-spacing-4);}.topbar {height:60px;padding:0 var(--g-spacing-4);}.breadcrumbs>span {display:none;}.breadcrumbs>svg:nth-child(2) {display:none;}.topbar-actions {gap:var(--g-spacing-1);}.topbar-divider {display:none;}.page-heading {align-items:flex-start;flex-direction:column;gap:var(--g-spacing-4);}.heading-actions {width:100%;}.stats-grid {grid-template-columns:repeat(2,minmax(0,1fr));}.stat-value.revenue {--g-text-display-1-font-size:20px;}.stat-bottom {line-height:16px;white-space:normal;}.stat-card {padding:var(--g-spacing-3);}.stat-top {font-size:10px;}.stat-icon {width:24px;height:24px;}.panel-heading {padding:var(--g-spacing-4);}.updated {display:none;}.table-toolbar {padding:var(--g-spacing-3);}.filter-actions {width:100%;gap:var(--g-spacing-1);}.group-select {min-width:0;flex:1;}.toolbar-divider {display:none;}.filter-actions .g-button {--g-button-padding:8px;}.grouping-hint {padding:var(--g-spacing-2) var(--g-spacing-3);font-size:9px;}.grouping-hint>svg {display:none;}.table-footer {flex-direction:column;align-items:flex-start;padding:var(--g-spacing-3);}.pagination {gap:0;flex-wrap:wrap;}.pagination>span:first-child {display:none;}.pagination-divider {margin:0 var(--g-spacing-2);}.page-footer {line-height:17px;flex-direction:column;gap:var(--g-spacing-2);}.users-grid {grid-template-columns:1fr;}.secondary-panel .panel-heading {align-items:flex-start;flex-direction:column;}.activity-row {flex-wrap:wrap;}.activity-row>strong {margin-left:auto;}.heading-line h1 {--g-text-display-1-font-size:25px;}.toast {width:calc(100vw - 32px);}.settings-panel {padding:var(--g-spacing-4);}}
EOF
