import * as React from 'react';
import { getCoreRowModel, getExpandedRowModel, getFilteredRowModel, getGroupedRowModel, getSortedRowModel, useReactTable, } from '@tanstack/react-table';
export const useTable = (options) => {
    // Keep default factory identities stable so table render versions change only with input data or state.
    const rowModelFactories = React.useMemo(() => ({
        getCoreRowModel: getCoreRowModel(),
        getExpandedRowModel: getExpandedRowModel(),
        getGroupedRowModel: getGroupedRowModel(),
        getSortedRowModel: getSortedRowModel(),
        getFilteredRowModel: getFilteredRowModel(),
    }), []);
    const tableOptions = {
        ...options,
